{
  "title": "Slow Start, Sea Breeze",
  "summary": "A gentle day that begins late, stays close to the water, and ends with a quiet sunset by the bay.",
  "stops": [
    {
      "poi_id": "p8",
      "kind": "activity",
      "must_do_id": null,
      "note": "A slow morning still deserves sand between the toes. An Bang is my kind of welcome mat.",
      "must_do_id": null
    },
    {
      "poi_id": "p13",
      "kind": "meal",
      "must_do_id": null,
      "note": "Crew of one, plate of chicken rice, zero rush. This is how you do a late lunch in area B."
    },
    {
      "poi_id": "p16",
      "kind": "activity",
      "must_do_id": null,
      "note": "A little green pause after eating, close by and easy on the legs. Even a langur approves of shade."
    },
    {
      "poi_id": "p82",
      "kind": "activity",
      "must_do_id": null,
      "note": "We drift over to the bay for the golden hour. Phạm Văn Đồng beach knows how to end a day."
    },
    {
      "poi_id": "p50",
      "kind": "meal",
      "must_do_id": null,
      "note": "Dinner stays local and noodle-warm. Mì Quảng Nhung keeps the evening simple and tasty."
    }
  ]
}
